<?php

namespace App\Services\Mail;

use Illuminate\Mail\Mailable;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Mail;
use Throwable;

class SafeMailSender
{
    /**
     * Send a mailable with structured logging on render or send failure.
     *
     * Unlike AuditMailer (which persists to AuditEmailLog), this service is
     * for non-audit mail paths that previously used the Mail facade directly
     * with no error visibility. It logs via Log::error + report() and always
     * rethrows so the caller (queue job, command, etc.) can decide on retries.
     */
    public function send(Mailable $mailable, string $recipient): void
    {
        $mailableName = class_basename($mailable);

        try {
            $mailable->render();
        } catch (Throwable $e) {
            Log::error('Mailable render failed', [
                'mailable' => $mailableName,
                'recipient' => $recipient,
                'exception' => $e->getMessage(),
            ]);
            report($e);

            throw $e;
        }

        try {
            Mail::to($recipient)->send($mailable);
        } catch (Throwable $e) {
            Log::error('Mailable send failed', [
                'mailable' => $mailableName,
                'recipient' => $recipient,
                'exception' => $e->getMessage(),
            ]);
            report($e);

            throw $e;
        }
    }
}
